const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function upstreamEnvelope(){return `<svg class="upstream-envelope" viewBox="0 0 420 215" aria-hidden="true"><path d="M14 14h392v187H14Z" fill="#e9f4f5" stroke="#203d50" stroke-width="3"/><path d="m15 16 195 124L405 16M15 200l137-108m254 108L268 92" fill="none" stroke="#8dafb4" stroke-width="2"/><path d="M336 35h45v54h-45Z" fill="#784166"/><path d="m346 65 13-17 13 17-13 14Z" fill="none" stroke="#fffefa" stroke-width="2"/><path d="M38 155q35-12 67 0m-67 13q35-12 67 0" stroke="#14757a" stroke-width="3" fill="none"/></svg>`;}
export function upstreamQuestionIcon(index=0){const shapes=['<path d="M12 4v16m-4-12 4-4 4 4M6 20h12"/>','<path d="M5 5h14M5 12h14M5 19h14M9 3v18"/>','<path d="M6 3h12v18H6zM9 8h6m-6 4h6m-6 4h4"/>','<path d="M3 8h7v12H3zM14 4h7v16h-7zM7 4l3-2m4 20 3 1"/>'];return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7">${shapes[index%shapes.length]}</svg>`;}
export function upstreamDrawingText(post,highlight=''){const {reference,unit,step,max,estimate}=post;const count=max/step;const text={reference:`Start at the fixed line marked 0 ${unit}. It is Vadoalto's chosen reference, labelled ${reference}.`,marks:`Each interval between marks is ${step} ${unit}. ${count} equal intervals above 0 reach ${max} ${unit}.`,estimate:`Nuria reports about ${estimate} ${unit} above her own fixed line labelled ${reference}. It is an estimate in her letter, not an exact reading you can make from this sketch.`};return highlight?text[highlight]||'':`Nuria's sketch of Vadoalto's post. The fixed starting line is labelled ${reference}. Marks are ${step} ${unit} apart. The dashed storm line shows Nuria's reported estimate: about ${estimate} ${unit} above that line. This sketch alone does not let us measure exactly ${estimate} ${unit}.`;}
export function upstreamPostDrawing(post,highlight=''){const marks=Array.from({length:post.max/post.step+1},(_,i)=>i*post.step);const y=n=>300-250*n/post.max;return `<figure class="upstream-drawing" data-upstream-drawing><div class="upstream-post-sketch" style="height:${Math.max(250,marks.length*28+50)}px"><svg viewBox="0 0 250 350" aria-hidden="true"><path d="m86 20 68 4-5 320-60-2Z" fill="#c6ac83" stroke="#644f39" stroke-width="2"/><path d="m105 28-3 300m27-295-4 299m13-275-3 235" stroke="#ad8e61" fill="none"/><path d="M12 324q40-8 65 0t68 0 84 0" stroke="#83b3b8" stroke-width="2" fill="none"/>${marks.map(n=>`<path d="M78 ${y(n)}h85" stroke="${n===0?'#14757a':'#203d50'}" stroke-width="${(highlight==='reference'&&n===0)||highlight==='marks'?5:2}"/>`).join('')}<path d="M32 ${y(post.estimate)}h180" stroke="#784166" stroke-width="${highlight==='estimate'?5:3}" stroke-dasharray="7 5"/></svg><div class="upstream-mark-labels">${marks.map(n=>`<span style="top:${y(n)/350*100}%">${esc(n)} ${esc(post.unit)}</span>`).join('')}</div></div><div class="upstream-drawing-readout"><p><strong>Fixed starting line: 0 ${esc(post.unit)}</strong> · ${esc(post.reference)}</p><p>Equal marks: ${esc(post.step)} ${esc(post.unit)} apart</p><p class="upstream-estimate"><strong>Nuria reports about ${esc(post.estimate)} ${esc(post.unit)}</strong> above her own fixed line</p><p>An estimate in her letter; this sketch does not give an exact reading.</p></div><figcaption><details class="upstream-sketch-description"><summary>Read the sketch</summary><p class="upstream-mark-list">Marked levels: ${marks.map(n=>`${esc(n)} ${esc(post.unit)}`).join(', ')}</p><p>${esc(upstreamDrawingText(post))}</p></details></figcaption>${highlight?`<p class="upstream-highlight" role="status">${esc(upstreamDrawingText(post,highlight))}</p>`:''}</figure>`;}
